with valid as (select *, case when txn_type = 'DEBIT' then 1 else 0 end is_debit, coalesce(merchant, 'N/A') resolved_merchant from transactions where txn_time > timestamp '2023-06-29 22:00:00' and is_flagged), gaps as (select *, case when lag(txn_time) over (partition by merchant order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by merchant order by txn_time, id) + interval '14' day then 1 else 0 end as is_new_burst from valid), sessions_transactions as (select *, sum(is_new_burst) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as island_id from gaps) select island_id, date_trunc('year', txn_time) as year_start, max(txn_time) as last_seen, size(collect_set(merchant)) as num_merchants, min(txn_time) as first_seen from sessions_transactions group by island_id, date_trunc('year', txn_time) order by year_start desc nulls first
